import {
  commandKey,
  walkCommands,
  type ArgumentSchema,
  type OptionSchema,
  type Schema,
  type ValueType,
} from "@schema";

const TS_TYPES: Readonly<Record<ValueType, string>> = {
  string: "string",
  boolean: "boolean",
};

export function emitDts(schema: Schema): string {
  const out = [
    "// Generated by cdcl. Do not edit.",
    "",
    "export interface CDLSchema {",
    "  readonly commands: {",
  ];

  for (const { path, command } of walkCommands(schema.root)) {
    const properties = Object.entries(command.properties).map(
      ([key, value]) => `readonly ${member(key)}: ${JSON.stringify(value)}`
    );

    out.push(`    readonly ${JSON.stringify(commandKey(path))}: {`);
    out.push(`      readonly args: ${object(command.arguments.map(argumentField))};`);
    out.push(`      readonly options: ${object(command.options.filter(o => !o.shortCircuit).map(optionField))};`);
    out.push(`      readonly properties: ${object(properties)}`);
    out.push(`    };`)
  }

  out.push("  };", "}", "", 'export type CommandPath = keyof CDLSchema["commands"];', "");
  return out.join("\n");
}

function argumentField(arg: ArgumentSchema): string {
  const base = TS_TYPES[arg.type];
  const type = arg.list ? `readonly ${base}[]` : arg.required ? base : `${base} | undefined`;
  return `readonly ${member(arg.name)}: ${type}`;
}

function optionField(option: OptionSchema): string {
  const base = TS_TYPES[option.type];
  const type = option.list
    ? `readonly ${base}[]`
    : option.type === "boolean"
      ? base
      : `${base} | undefined`;

  return `readonly ${member(option.name)}: ${type}`;
}

function member(name: string): string {
  return /^[A-Za-z_$][\w$]*$/.test(name) ? name : JSON.stringify(name);
}

function object(fields: readonly string[]): string {
  if (fields.length === 0) return `Record<string, never>`;
  return ["{", ...fields.map(f => `        ${f};`), "      }"].join("\n");
}
